-- does nothing but decode and run the real script below. edit KEY/PAYLOAD together, never separately.

local KEY = {141, 99, 82, 182, 109, 171, 237, 102, 241, 215, 147, 69, 74, 23, 73, 146, 183, 187, 105, 154, 254, 117, 216, 25, 137, 172, 160, 69, 162, 12, 171, 233}

local B64CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64LOOKUP = {}
for i = 1, #B64CHARS do
    B64LOOKUP[B64CHARS:byte(i)] = i - 1
end

local function b64decode(data)
    data = data:gsub("[^%w+/]", "") -- strip newlines/padding/anything stray; trailing '=' just drops unneeded bits below
    local out = {}
    local n = 0
    local bits = 0
    local acc = 0
    for i = 1, #data do
        local v = B64LOOKUP[data:byte(i)]
        if v then
            -- bit32 ops stay inside 32 bits: acc never holds more than 13 bits before a flush, so no precision loss
            acc = bit32.bor(bit32.lshift(acc, 6), v)
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                n = n + 1
                out[n] = string.char(bit32.band(bit32.rshift(acc, bits), 0xFF))
            end
        end
    end
    return table.concat(out)
end

local function xorDecode(data, key)
    local out = {}
    local klen = #key
    for i = 1, #data do
        local kb = key[((i - 1) % klen) + 1]
        out[i] = string.char(bit32.bxor(data:byte(i), kb))
    end
    return table.concat(out)
end

